begin;
do $check$ begin if exists(select 1 from public.academy_content where id in ('bar-wine-guide','bar-beer-guide')) then raise exception 'A guide already exists; compare before updating';end if;end $check$;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) select id,kind,title,course_id,payload,published,restaurant_id,department from jsonb_populate_record(null::public.academy_content,$guide${"id":"bar-wine-guide","kind":"material","title":"База знаний бара: вино","course_id":null,"restaurant_id":null,"department":"Бар","published":true,"payload":{"id":"bar-wine-guide","title":"База знаний бара: вино","brand":"common","format":"handbook","description":"14 разделов: сорта, стили, производство, сладость, игристое, подача, хранение и сочетания.","verifiedAt":"2026-10-29","sectionCount":14,"body":"<p>Проверено 29 октября 2026 · Справочник для команды бара двух брендов</p><p>Профили сортов и стилей, гастрономические сочетания и температуры — учебные ориентиры. Характеристики конкретной позиции подтверждаем по этикетке и карточке производителя. Рецептура, выход порции, оборудование и сроки хранения определяются действующими картами бара.</p><details open><summary>1. Что такое вино и какие бывают стили</summary><div>\n<p>Вино получают частичным или полным алкогольным брожением свежего винограда или виноградного сусла. Дрожжи перерабатывают сахара в этанол и углекислый газ. Название сорта, цвет, сладость, крепость и происхождение — разные характеристики, их нельзя подменять друг другом.</p>\n<ul><li><strong>Тихое:</strong> без выраженного игристого характера; белое, красное, розовое и другие стилистические исполнения.</li><li><strong>Игристое:</strong> растворённый углекислый газ образует пузырьки при открывании и наливе. Метод получения газа и защищённое наименование уточняем отдельно.</li><li><strong>Креплёное:</strong> в производстве добавляют спирт. Стиль бывает сухим и сладким; портвейн и херес различаются по технологии.</li><li><strong>Ароматизированное:</strong> винная основа с ароматическими компонентами; вермут имеет отдельные правила и не является обычным тихим вином с сортовым ароматом.</li></ul>\n<p><strong>Стилистика</strong> — краткий портрет: например, «сухое, лёгкое, свежее, цитрусовое». <strong>Дегустационные характеристики</strong> раскрывают конкретные ароматы, кислотность, танины, тело и послевкусие. Слово «фруктовое» не означает «сладкое», а «насыщенное» не означает «креплёное».</p><p><strong>Источники:</strong> <a href=\"https://www.oiv.int/standards/international-code-of-oenological-practices/part-i-definitions/wines\" target=\"_blank\" rel=\"noopener noreferrer\">OIV: определение вина и сахар</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/october/03/how-many-wine-types-and-styles-are-there/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: типы и стили вина</a></p></div></details><details><summary>2. Производство: от винограда до бутылки</summary><div>\n<p>Типичный путь: сбор и сортировка → получение сусла → брожение → отделение твёрдых частиц и работа с осадком → созревание, возможный купаж → подготовка к розливу. Последовательность прессования и брожения зависит от желаемого стиля.</p>\n<ul><li><strong>Белое:</strong> сок обычно отделяют от кожицы до брожения. Из тёмного винограда тоже можно получить белое вино, если ограничить извлечение цвета.</li><li><strong>Красное:</strong> брожение обычно проходит с кожицей; она даёт основную часть цвета и часть танинов. У большинства сортов сок почти бесцветный, но существуют красномякотные исключения.</li><li><strong>Розовое:</strong> цвет часто получают коротким контактом с кожицей или прямым прессованием тёмного винограда. Это не обязательно смесь готового белого и красного; смешивание допускается в отдельных категориях.</li><li><strong>Оранжевое / янтарное:</strong> белый виноград с продолжительным контактом с кожицей; возможны заметные танины. Апельсины для этого не нужны.</li></ul>\n<p>Нержавеющая сталь помогает сохранять свежий профиль без древесной ароматики. Дуб может добавлять пряные и ванильные оттенки. Малолактическое преобразование смягчает характер кислотности; выдержка на осадке может менять текстуру. Ни одна операция не обязательна для всех вин.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2021/september/23/what-determines-the-colour-of-wine\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: цвет и контакт с кожицей</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/what-is-orange-wine-understanding-skin-contact-white-wines\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: оранжевые вина</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2022/may/24/behind-the-grape-chardonnay-in-the-us/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: стили Chardonnay</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/understanding-acidity-in-wine\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: кислотность</a></p></div></details><details><summary>3. Вкус: сахар, кислотность, танины и тело</summary><div>\n<ul><li><strong>Сладость:</strong> ощущение остаточных сахаров. Спелый аромат персика или ванили не доказывает наличие высокой сладости.</li><li><strong>Кислотность:</strong> свежесть и слюноотделение; не путать с теплом от алкоголя. Даже сладкое вино может быть высококислотным.</li><li><strong>Танины:</strong> подсушивающее, вяжущее ощущение на дёснах и щеках. Особенно заметны в красных и некоторых янтарных винах; не являются синонимом кислоты.</li><li><strong>Тело:</strong> общее ощущение веса и полноты во рту — лёгкое, среднее или полное. Это не оценка качества.</li><li><strong>Алкоголь:</strong> влияет на тепло и вес; фактическую крепость берём с этикетки.</li><li><strong>Послевкусие:</strong> характер и длительность ощущений после глотка. Долгое горькое или неприятное послевкусие само по себе не признак качества.</li></ul>\n<p>Первичные ароматы связаны с виноградом и брожением, вторичные — с отдельными приёмами производства, третичные — с развитием вина. Яблоко, смородина, перец и кожа в описании — узнаваемые ассоциации, а не обязательные добавки.</p>\n<p><strong>Фраза для гостя:</strong> «Сухое, с яркой свежестью и цитрусовыми нотами; лёгкое по телу». Она полезнее, чем просто «очень мягкое». Один сорт может давать разные результаты в зависимости от места, урожая и решений винодела.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/understanding-acidity-in-wine\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: кислотность</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/strawberry-pepper-and-petrol-why-wine-smells-the-way-it-does\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: откуда берутся ароматы</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/october/03/how-many-wine-types-and-styles-are-there/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: типы и стили вина</a></p></div></details><details><summary>4. Сладость тихого и игристого: две разные шкалы</summary><div>\n<h3>Тихое вино</h3><p>По определениям OIV сухое вино содержит не более 4 г/л сахара либо до 9 г/л, если общая кислотность, выраженная в винной кислоте, отстаёт от сахара не более чем на 2 г/л. Поэтому правило «сухое — всегда строго до 4 г/л» неполно. Для остальных обозначений и конкретной бутылки смотрим применимую маркировку и технический лист. Национальные требования могут различаться.</p>\n<h3>Игристое: ориентиры по обозначениям Champagne</h3><ul><li><strong>Brut Nature:</strong> менее 3 г/л и без добавления сахара после вторичного брожения.</li><li><strong>Extra Brut:</strong> 0–6 г/л.</li><li><strong>Brut:</strong> менее 12 г/л.</li><li><strong>Extra Dry:</strong> 12–17 г/л — слаще brut.</li><li><strong>Sec / Dry:</strong> 17–32 г/л.</li><li><strong>Demi-Sec:</strong> 32–50 г/л.</li><li><strong>Doux:</strong> более 50 г/л.</li></ul>\n<p>Это ориентиры категорий, а не измерение конкретной бутылки; нормативные допуски проверяем в спецификации. Диапазоны не всегда взаимоисключающие. Надпись Extra Dry нельзя переводить гостю как «самое сухое». Riesling может быть и сухим, и сладким; названия сорта для определения сахара недостаточно.</p><p><strong>Источники:</strong> <a href=\"https://www.oiv.int/standards/international-code-of-oenological-practices/part-i-definitions/wines\" target=\"_blank\" rel=\"noopener noreferrer\">OIV: определение вина и сахар</a> · <a href=\"https://www.champagne.fr/fr/deguster-le-champagne/preparez-vous-a-deguster-du-champagne/comprendre-une-etiquette\" target=\"_blank\" rel=\"noopener noreferrer\">Comité Champagne: обозначение сахара</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2024/july/17/understanding-riesling-in-germany/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Riesling</a></p></div></details><details><summary>5. Белые сорта: как объяснить разницу</summary><div>\n<p>Ниже типичные профили, а не обещание характеристик любой бутылки. Конкретные сахар, регион, выдержку и вкус сверяем с карточкой вина.</p>\n<ul><li><strong>Шардоне / Chardonnay:</strong> от свежего цитрусово-яблочного до более полного, со спелыми фруктами. Дуб и малолактическое преобразование могут добавлять тостовые, сливочные и маслянистые впечатления. Шардоне не обязательно выдержан в бочке.</li><li><strong>Совиньон Блан / Sauvignon Blanc:</strong> часто яркая кислотность, цитрус, крыжовник, травяные оттенки; встречаются тропические и более округлые варианты. Марлборо, Луара и другие регионы не дают полностью одинаковый профиль.</li><li><strong>Рислинг / Riesling:</strong> обычно выраженная кислотность; яблоко, цитрус, цветы, в более спелых стилях косточковые фрукты. Диапазон сладости очень широкий; возрастные ноты оцениваем в контексте вина.</li><li><strong>Пино Гриджо / Pinot Grigio, Пино Гри / Pinot Gris:</strong> один сорт под разными названиями. Часто встречается лёгкий яблочно-грушевый стиль, но возможны более полные и насыщенные версии. Название не фиксирует сахар или регион.</li></ul>\n<p><strong>Как предложить:</strong> «Если хочется ярче и свежее — посмотрим Совиньон; если полнее и округлее — подходящее Шардоне. Уточню, нравится ли вам дубовая ароматика». Затем называем конкретную позицию из меню и её цену.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2022/may/24/behind-the-grape-chardonnay-in-the-us/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: стили Chardonnay</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2020/may/01/understanding-grapes-spotlight-on-sauvignon-blanc\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Sauvignon Blanc</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2024/july/17/understanding-riesling-in-germany/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Riesling</a> · <a href=\"https://www.wsetglobal.com/media/13022/wset_l2wines_sessionplans_en_may2023_issue2.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Pinot Grigio / Pinot Gris</a></p></div></details><details><summary>6. Красные сорта: фрукт, структура и насыщенность</summary><div>\n<ul><li><strong>Каберне Совиньон / Cabernet Sauvignon:</strong> часто чёрная смородина и другие тёмные ягоды, заметная танинная структура. С выдержкой и дубом возможны дополнительные древесные и пряные оттенки. Не каждый образец одинаково тяжёлый.</li><li><strong>Мерло / Merlot:</strong> часто слива, вишня и округлая текстура; танины обычно воспринимаются доступнее, но выражение зависит от зрелости и производства. Мерло не обязательно сладкое.</li><li><strong>Пино Нуар / Pinot Noir:</strong> нередко красные ягоды, вишня, более лёгкое или среднее тело, свежесть и относительно деликатные танины. Светлый цвет не означает слабый вкус или плохое качество.</li><li><strong>Сира / Syrah, Шираз / Shiraz:</strong> один сорт; тёмные фрукты и возможные перечные, пряные оттенки. В прохладных местах перец часто заметнее, в тёплых профиль может быть более спелым и полным.</li></ul>\n<p>Купаж — вино из нескольких компонентов, например сортов. Он может быть способом добиться баланса, а не признаком низкого качества. Не называем любое французское красное Каберне, любое австралийское — Ширазом и любое лёгкое красное — Пино Нуаром.</p>\n<p><strong>Как предложить:</strong> «Предпочитаете лёгкое ягодное или более насыщенное и терпкое?» Слово «терпкое» поясняем как подсушивающее ощущение, если гостю это помогает.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/december/19/awesome-alternative-wine-types\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: сорта и купажи</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2024/five-merlot-facts-every-wine-lover-should-know\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Merlot</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/august/coast-to-coast-pinot-noir-in-north-america\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Pinot Noir</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/what-gives-syrahshiraz-its-peppery-spice/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Syrah / Shiraz</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2021/september/23/what-determines-the-colour-of-wine\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: цвет и контакт с кожицей</a></p></div></details><details><summary>7. Происхождение и этикетка</summary><div>\n<p>Для работы с бутылкой проверяем: производитель и название, страна, регион или защищённое наименование, сорт или купаж, год урожая при наличии, сладость, крепость, объём, условия хранения и информацию об аллергенах. Регион не является названием сорта.</p>\n<h3>Несколько ориентиров</h3><p>В Бургундии важны Chardonnay и Pinot Noir; в Бордо — в том числе купажи Cabernet Sauvignon и Merlot, а также белые вина. Для Риохи важен Tempranillo, для Бароло — Nebbiolo. В Германии распространён Riesling, в новозеландском Марлборо — Sauvignon Blanc, в Чили встречаются международные сорта в разных долинах. Эти примеры не заменяют полную этикетку.</p>\n<p>AOC/AOP, DOC/DOCG и другие национальные обозначения связаны с происхождением и правилами производства; их нельзя расположить в одной универсальной мировой «лестнице качества». Слова Reserva и Grand Cru имеют значение только в своей системе. Год урожая не равен году розлива; отсутствие одного года на игристом может быть нормальной особенностью купажа.</p>\n<p>При продаже не угадываем происхождение по языку названия. Если сорт или срок выдержки не подтверждён, так и говорим и уточняем техническую информацию, вместо того чтобы дописывать детали по памяти.</p><p><strong>Источники:</strong> <a href=\"https://www.oiv.int/sites/default/files/publication/2025-03/OIV%20Wine%20Labelling%20Standard%20EN_2025%20complet.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">OIV: маркировка вина</a> · <a href=\"https://www.wsetglobal.com/media/13167/wset_l2wines_specification_en_may2023_issue2.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: программа по винам</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/december/19/awesome-alternative-wine-types\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: сорта и купажи</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2020/may/01/understanding-grapes-spotlight-on-sauvignon-blanc\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Sauvignon Blanc</a> · <a href=\"https://www.prosecco.wine/en/prosecco/\" target=\"_blank\" rel=\"noopener noreferrer\">Consorzio Prosecco DOC: Glera и производство</a></p></div></details><details><summary>8. Игристое: методы и названия</summary><div>\n<ul><li><strong>Традиционный метод:</strong> вторичное брожение в бутылке, затем работа с дрожжевым осадком и его удаление. Выдержка на осадке может давать хлебные и бриошевые оттенки.</li><li><strong>Резервуарный метод, Martinotti–Charmat:</strong> вторичное брожение в закрытом резервуаре; часто используется для сохранения свежей фруктовой ароматики.</li><li><strong>Другие способы:</strong> существуют методы с завершением первичного брожения в бутылке и другие технологии. Не все пузырьки получают одинаковым способом.</li></ul>\n<p><strong>Champagne</strong> — защищённое наименование Шампани, а не общее название любого игристого. <strong>Prosecco DOC</strong> связано со своей зоной и правилами, основной сорт — Glera; привычный игристый стиль производится резервуарным методом. Сухость определяется маркировкой, а не страной или названием.</p>\n<p><strong>Blanc de Blancs</strong> указывает на белые сорта, <strong>Blanc de Noirs</strong> — на тёмные; это не шкала сладости. Розовый цвет не означает сладость. Мелкие пузырьки и красивая пена сами по себе не позволяют точно установить метод, возраст или цену.</p>\n<p>Для рекомендации уточняем желаемую сладость и профиль: свежий фруктовый либо более хлебный и сложный. Не обещаем, что любое игристое обязательно должно пахнуть дрожжами.</p><p><strong>Источники:</strong> <a href=\"https://www.oiv.int/public/medias/7291/oiv-sparkling-focus-2020.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">OIV: производство игристых</a> · <a href=\"https://www.prosecco.wine/en/prosecco/\" target=\"_blank\" rel=\"noopener noreferrer\">Consorzio Prosecco DOC: Glera и производство</a> · <a href=\"https://www.champagne.fr/fr/deguster-le-champagne/preparez-vous-a-deguster-du-champagne/comprendre-une-etiquette\" target=\"_blank\" rel=\"noopener noreferrer\">Comité Champagne: обозначение сахара</a> · <a href=\"https://www.champagne.fr/en/champagne-frequently-asked-questions\" target=\"_blank\" rel=\"noopener noreferrer\">Comité Champagne: подача и открывание</a></p></div></details><details><summary>9. Сладкие, креплёные и особые стили</summary><div>\n<p>Сладкое вино можно получить разными способами: оставить часть сахара при брожении, использовать более концентрированное сырьё, подвяленные или замороженные ягоды, виноград с благородной гнилью в подходящих условиях. Сладость не доказывает добавление обычного сахара в готовое вино. Благородная гниль и испорченные ягоды — не одно и то же.</p>\n<p>При креплении добавляют спирт. Для портвейна характерна остановка брожения с сохранением сахара; сухие стили хереса устроены иначе и могут иметь оксидативные и биологические тона. Тёмный цвет креплёного вина не означает сладость.</p>\n<p>Квеври, амфора, бетон и дуб — разные ёмкости, а не автоматическая гарантия «натуральности». Оранжевое вино не обязано быть окисленным. «Органическое», «биодинамическое» и «натуральное» не следует считать взаимозаменяемыми словами; точные утверждения о сертификации требуют подтверждения производителя.</p>\n<p>Сульфиты и прочие сведения об аллергенах проверяем по маркировке. Нельзя обещать отсутствие аллергенов, похмелья или лечебный эффект на основании цвета, сладости, натуральной пробки либо рекламного описания.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2024/july/17/understanding-riesling-in-germany/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: Riesling</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/what-is-orange-wine-understanding-skin-contact-white-wines\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: оранжевые вина</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/october/03/how-many-wine-types-and-styles-are-there/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: типы и стили вина</a></p></div></details><details><summary>10. Дегустация и описание без сложных слов</summary><div>\n<ol><li><strong>Посмотрите:</strong> цвет, интенсивность, прозрачность и наличие осадка. Сначала учитываем стиль и возраст.</li><li><strong>Понюхайте:</strong> чистота и выраженность аромата; затем две-три понятные ассоциации. Не нужно перечислять десять фруктов.</li><li><strong>Оцените вкус:</strong> сахар, кислотность, танины для соответствующих вин, тело, алкоголь, основные оттенки и послевкусие.</li><li><strong>Сопоставьте:</strong> совпадает ли профиль с карточкой и ожиданием от стиля, нет ли признаков дефекта.</li><li><strong>Сформулируйте:</strong> стиль → два вкусовых ориентира → подходящая ситуация или блюдо.</li></ol>\n<p><strong>Пример:</strong> «Белое сухое, свежее и лёгкое, с цитрусом и зелёным яблоком. Подойдёт, если хочется яркой кислотности к лёгкой закуске». Это пример формулировки, не описание любой бутылки сорта.</p>\n<p>Кислотность не оценивают по слезам на бокале, а возраст — только по цвету. Разные люди по-разному распознают ароматы. При рабочей дегустации соблюдаем правила заведения; обучение не требует употребления полной порции.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/strawberry-pepper-and-petrol-why-wine-smells-the-way-it-does\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: откуда берутся ароматы</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/understanding-acidity-in-wine\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: кислотность</a> · <a href=\"https://www.wsetglobal.com/media/13167/wset_l2wines_specification_en_may2023_issue2.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: программа по винам</a></p></div></details><details><summary>11. Подача, открывание и декантация</summary><div>\n<p>Перед подачей сверяем бутылку, год при наличии, цену и объём заказа. Используем чистый бокал без постороннего запаха, держим его за ножку или основание, не касаемся края и внутренней поверхности. Порядок презентации, пробного налива и размер порции — по стандарту заведения.</p>\n<p><strong>Температурные ориентиры:</strong> лёгкие белые и розовые — охлаждёнными; полные белые примерно 10–13°C; средние и полные красные — примерно 15–18°C. Для Champagne Comité Champagne рекомендует 8–10°C. Это отправные точки, а не обязательная температура любого вина; конкретную бутылку подаём по карте и рекомендациям производителя. Сильное переохлаждение скрывает аромат, перегрев усиливает ощущение алкоголя.</p>\n<p><strong>Игристое:</strong> охлаждаем, направляем горлышко от людей и хрупких предметов. Постоянно контролируем пробку рукой, аккуратно ослабляем мюзле; держим бутылку под углом и медленно вращаем её, удерживая пробку. Открываем тихо и управляемо, не выпускаем пробку в зал. Сабраж не часть стандартного сервиса.</p>\n<p><strong>Декантация:</strong> применяется для отделения осадка и иногда для аэрации конкретного вина. Не нужна каждому красному, а длительный контакт с воздухом может ухудшить деликатное зрелое вино. Решение принимаем по бутылке и стандарту, а не по единому таймеру.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2022/april/26/ideal-serving-temperatures-and-top-tips-for-wine-storage\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: температура и хранение</a> · <a href=\"https://www.champagne.fr/en/champagne-frequently-asked-questions\" target=\"_blank\" rel=\"noopener noreferrer\">Comité Champagne: подача и открывание</a> · <a href=\"https://www.wsetglobal.com/media/13167/wset_l2wines_specification_en_may2023_issue2.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: программа по винам</a></p></div></details><details><summary>12. Хранение и контроль открытых бутылок</summary><div>\n<p>Закрытые бутылки защищаем от перегрева, прямого света и резких колебаний температуры. Для длительного хранения важна стабильная прохлада. Укупорку и положение бутылки учитываем отдельно: натуральную пробку обычно держат в контакте с вином, винтовая крышка не требует такого положения. Не каждое вино предназначено для многолетней выдержки.</p>\n<h3>После вскрытия</h3><ul><li>Сразу фиксируем дату и время, если это предусмотрено картой хранения.</li><li>Закрываем бутылку после налива, храним охлаждённой по инструкции. Красное тоже можно хранить в холодильнике, затем довести до температуры подачи.</li><li>Для тихих вин используем предусмотренную систему сохранения; её результат зависит от оборудования, вина и соблюдения процедуры.</li><li>Для игристого нужна подходящая герметичная пробка и оборудование именно для игристого. Обычный вакуумный насос для тихого вина не применяем.</li><li>Контролируем качество перед продажей и соблюдаем установленный срок. Не назначаем всем винам одинаковые «три дня» или «неделю».</li></ul>\n<p>Срок в учебной статье не заменяет карту бара. Ложка в горлышке не является способом сохранения пузырьков. Остатки разных бутылок не объединяем без предусмотренной процедуры и прослеживаемости.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2022/april/26/ideal-serving-temperatures-and-top-tips-for-wine-storage\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: температура и хранение</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/march/07/the-best-ways-to-preserve-wine-after-opening\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: открытая бутылка</a></p></div></details><details><summary>13. Дефекты и работа с замечанием гостя</summary><div>\n<ul><li><strong>Пробковый тон:</strong> затхлый, сырой картон, приглушённая фруктовость; часто связан с TCA. Крошка пробки в бокале — другая ситуация.</li><li><strong>Нежелательное окисление:</strong> потеря свежести, побурение, неожиданные ноты залежавшегося яблока или ореха для стиля, который должен быть свежим. В оксидативном хересе похожий профиль может быть нормой.</li><li><strong>Перегрев:</strong> потускневший, несвежий фруктовый профиль и возможные проблемы с укупоркой.</li><li><strong>Другие посторонние запахи:</strong> выраженный уксусный, растворительный или сернистый тон требуют оценки ответственного; не маскируем их охлаждением или длительным проветриванием.</li></ul>\n<p>Осадок и винные кристаллы сами по себе не доказывают порчу. Мутность оцениваем относительно технологии. Описание аромата не является лабораторным диагнозом.</p>\n<p><strong>При жалобе:</strong> выслушать без спора → остановить дальнейшую подачу спорной бутылки → пригласить ответственного и сравнить с ожидаемым профилем → заменить или решить вопрос по стандарту → зафиксировать бутылку и партию. Не объясняем дефект «особенностью дорогого вина», если это не подтверждено.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/august/24/common-wine-faults-and-how-to-spot-them\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: дефекты вина</a> · <a href=\"https://www.wsetglobal.com/media/13167/wset_l2wines_specification_en_may2023_issue2.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: программа по винам</a></p></div></details><details><summary>14. Гастрономия и рекомендация гостю</summary><div>\n<p>Сопоставляем интенсивность блюда и вина, затем учитываем соус, жирность, соль, сладость и остроту. Правило «белое к рыбе, красное к мясу» слишком грубое: способ приготовления и соус могут быть важнее основного продукта.</p>\n<ul><li><strong>Лёгкие закуски и морепродукты:</strong> свежий белый или подходящее игристое — возможная отправная точка.</li><li><strong>Сливочные блюда:</strong> полное белое может поддержать текстуру, а более кислотное дать контраст.</li><li><strong>Жареное мясо:</strong> структурное красное часто работает с насыщенностью и жиром.</li><li><strong>Десерт:</strong> сухое вино на фоне сладкой еды может казаться резче; подбираем сладость и интенсивность осознанно.</li><li><strong>Острые блюда:</strong> высокий алкоголь и танины могут усиливать неприятное жжение. Часто удобнее более лёгкий, фруктовый и менее танинный стиль; вкусы гостя важнее формулы.</li></ul>\n<p>Это примеры сочетаний, а не обязательные правила. Уточняем: цвет или игристое → сладость → лёгкое или насыщенное → желаемый бюджет → блюдо. Предлагаем одну-две реальные позиции, называем различие и цену.</p>\n<p><strong>Шаблон карточки:</strong> вино и цвет; страна и регион; сахар; виноград; стилистика; дегустационные характеристики; гастрономия; способ производства. Подтверждённые сведения о бутылке отделяем от типичного профиля сорта.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2023/july/13/four-rules-to-masterful-food-and-wine-pairing\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: сочетание вина и еды</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/how-to-pair-drinks-with-spice\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: напитки и острые блюда</a></p></div></details>"}}$guide$::jsonb);
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) select id,kind,title,course_id,payload,published,restaurant_id,department from jsonb_populate_record(null::public.academy_content,$guide${"id":"bar-beer-guide","kind":"material","title":"База знаний бара: пиво","course_id":null,"restaurant_id":null,"department":"Бар","published":true,"payload":{"id":"bar-beer-guide","title":"База знаний бара: пиво","brand":"common","format":"handbook","description":"13 разделов: сырьё, стили, брожение, вкус, бокалы, розлив, хранение и сочетания.","verifiedAt":"2026-10-29","sectionCount":13,"body":"<p>Проверено 29 октября 2026 · Справочник для команды бара двух брендов</p><p>Профили сортов и стилей, гастрономические сочетания и температуры — учебные ориентиры. Характеристики конкретной позиции подтверждаем по этикетке и карточке производителя. Рецептура, выход порции, оборудование и сроки хранения определяются действующими картами бара.</p><details open><summary>1. Что такое пиво и из чего оно состоит</summary><div>\n<p>Пиво — сброженный напиток, обычно на основе зернового сырья, воды, хмеля и дрожжей. Солод даёт основу для получения сбраживаемых сахаров; дрожжи образуют алкоголь и углекислый газ. Дополнительные злаки, фрукты, пряности и другие ингредиенты зависят от рецептуры и стиля.</p>\n<ul><li><strong>Вода:</strong> среда производства; минеральный состав влияет на технологию и восприятие вкуса.</li><li><strong>Солод и зерно:</strong> дают зерновые, хлебные, тостовые, карамельные и обжаренные оттенки в зависимости от обработки.</li><li><strong>Хмель:</strong> источник горечи и ароматов — от трав, цветов и пряностей до цитруса, хвои и тропических фруктов.</li><li><strong>Дрожжи:</strong> создают не только алкоголь, но и часть ароматического профиля; характер зависит от культуры и условий брожения.</li></ul>\n<p>Хмель не является источником алкогольной крепости. Тёмный цвет не доказывает высокий алкоголь, а цитрусовый аромат не обязательно означает добавленный апельсин. При вопросе о составе или аллергенах проверяем этикетку и техническую информацию конкретного пива.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/how-to-become-a-better-beer-taster\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: дегустация пива</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/how-much-do-you-know-about-hops\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: хмель и способы охмеления</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/what-s-in-a-beer-colour-how-shades-tell-a-story/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: цвет пива</a></p></div></details><details><summary>2. Производство: основные этапы</summary><div>\n<ol><li><strong>Соложение:</strong> зерно замачивают, проращивают и сушат. Обработка формирует свойства и цвет солода.</li><li><strong>Дробление и затирание:</strong> в смеси зерна и воды ферменты превращают крахмал в более простые сахара.</li><li><strong>Отделение сусла:</strong> жидкую часть отделяют от зерновой дробины.</li><li><strong>Кипячение:</strong> формируют свойства сусла и обычно вносят хмель. Время и способ внесения влияют на горечь и аромат.</li><li><strong>Охлаждение и брожение:</strong> вносят культуру; сахара перерабатываются, формируется профиль.</li><li><strong>Созревание:</strong> напиток достигает нужного состояния; режим зависит от стиля.</li><li><strong>Подготовка и упаковка:</strong> возможны фильтрация, пастеризация, карбонизация или дображивание; не все операции применяют ко всему пиву.</li></ol>\n<p>Слова «нефильтрованное» и «непастеризованное» описывают разные операции. Они не означают автоматически «без добавок», «полезнее» или «всегда мутное». Осадок и прозрачность оценивают по конкретному продукту.</p>\n<p>Dry hopping — охмеление во время или после брожения преимущественно ради аромата; это не высушивание готового пива. Интенсивный хмелевой запах и высокая воспринимаемая горечь не всегда идут вместе.</p><p><strong>Источники:</strong> <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2017/04/American_Craft_Beer_Guide_English.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: этапы пивоварения</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/how-much-do-you-know-about-hops\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: хмель и способы охмеления</a></p></div></details><details><summary>3. Эль, лагер и смешанное брожение</summary><div>\n<p><strong>Эль</strong> обычно связан с элевыми культурами и более тёплым брожением. <strong>Лагер</strong> — с лагерными культурами и обычно более прохладным брожением и последующим созреванием. Это семейства по технологии, а не деление на светлое и тёмное.</p>\n<p>Лагер часто имеет чистый профиль, позволяющий отчётливо воспринимать солод и хмель. Эль может быть фруктовым или пряным, но бывает и очень сдержанным. Не устанавливаем одинаковую температуру брожения, крепость или сладость для всех представителей семейства.</p>\n<p>Существуют гибридные подходы, специальные культуры и смешанное брожение. В некоторых кислых и традиционных стилях работают дрожжи и бактерии; кислота может быть намеренной частью профиля. Спонтанное брожение не означает отсутствие контроля качества.</p>\n<p><strong>Как объяснить гостю:</strong> «Лагер — большое семейство. Здесь есть и лёгкие светлые, и тёмные солодовые стили». Если гость просит «простой лагер», уточняем горечь и насыщенность, а не выбираем только по цвету.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/more-than-just-a-cold-one-lager-uncovered\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: семейство лагеров</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/what-is-sour-beer-how-its-made-and-sour-beer-styles-to-try\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: кислые стили</a> · <a href=\"https://www.bjcp.org/download/2021_guidelines_consolidated-pdf\" target=\"_blank\" rel=\"noopener noreferrer\">BJCP: руководство по стилям</a></p></div></details><details><summary>4. Светлые и тёмные лагеры</summary><div>\n<ul><li><strong>International Pale Lager:</strong> обычно чистый профиль, умеренная насыщенность и доступный баланс солода и хмеля. Конкретные марки различаются.</li><li><strong>Pils / Pilsner:</strong> семейство светлых лагеров с заметным хмелевым балансом; немецкие и чешские исполнения не полностью одинаковы.</li><li><strong>Helles:</strong> светлый мюнхенский стиль, часто более мягкий и солодовый в сравнении с Pils.</li><li><strong>Vienna Lager / Märzen:</strong> янтарные солодовые направления с хлебными и тостовыми впечатлениями; не считаем их одним идентичным стилем.</li><li><strong>Dunkel / Schwarzbier:</strong> разные тёмные лагеры. Возможны хлебная глубина и мягкая обжаренность, но чёрный цвет не требует тяжёлого сладкого вкуса.</li><li><strong>Bock / Doppelbock:</strong> более насыщенные солодовые направления; фактическую крепость сверяем с бутылкой.</li></ul>\n<p>Это ориентиры для выбора, а не строгие границы каждой коммерческой марки. Для рекомендации сравниваем конкретные позиции: «Этот светлый мягче и хлебнее, этот суше и заметнее горчит». Не выдаём слово lager за сорт хмеля или гарантию одинакового вкуса.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/more-than-just-a-cold-one-lager-uncovered\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: семейство лагеров</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/what-s-in-a-beer-colour-how-shades-tell-a-story/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: цвет пива</a> · <a href=\"https://www.bjcp.org/download/2021_guidelines_consolidated-pdf\" target=\"_blank\" rel=\"noopener noreferrer\">BJCP: руководство по стилям</a></p></div></details><details><summary>5. Пшеничное пиво и фруктово-пряные стили</summary><div>\n<h3>Пшеница не означает один вкус</h3><p><strong>Немецкий Weissbier / Hefeweizen:</strong> характерны пшеничная текстура, высокая карбонизация и дрожжевые впечатления банана и гвоздики. Эти ноты могут появляться при брожении без добавления банана или гвоздики. Обычно горечь сдержанная.</p>\n<p><strong>Witbier:</strong> бельгийское направление, где традиционно встречаются цитрусовая цедра и кориандр. <strong>American Wheat:</strong> часто более чистый по брожению профиль, поэтому бананово-гвоздичные ноты не обязательны для любого пшеничного.</p>\n<p>Hefe указывает на дрожжевой характер исполнения, а прозрачность и осадок зависят от продукта. Не взбалтываем все бутылки автоматически. Если производитель предусматривает перенос дрожжевого осадка в бокал, действуем по его инструкции; если гость хочет чистый налив, уточняем возможность.</p>\n<p>Бельгийские эли и saison могут быть фруктовыми, пряными и сухими, но география сама по себе не доказывает состав. Слова dubbel, tripel и quadrupel не переводим как точное число брожений или универсальный множитель крепости.</p>\n<p><strong>Сервис:</strong> выбираем бокал с местом для пены, не добавляем лимон и другие гарниры без предусмотренной подачи или согласования с гостем.</p><p><strong>Источники:</strong> <a href=\"https://www.bjcp.org/style/2021/10/10A/\" target=\"_blank\" rel=\"noopener noreferrer\">BJCP: Weissbier</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/how-much-do-you-know-about-hops\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: хмель и способы охмеления</a> · <a href=\"https://www.bjcp.org/download/2021_guidelines_consolidated-pdf\" target=\"_blank\" rel=\"noopener noreferrer\">BJCP: руководство по стилям</a></p></div></details><details><summary>6. Pale Ale, IPA и охмелённые стили</summary><div>\n<p><strong>Pale Ale</strong> — широкая группа светлых элей с разным балансом. <strong>American IPA</strong> обычно заметно охмелён, с выраженными горечью и ароматом, поддержанными солодовой основой. Возможны цитрус, хвоя, смола, тропические и косточковые фруктовые впечатления.</p>\n<p><strong>West Coast IPA</strong> часто используют для более сухого и горького направления. <strong>Hazy / New England IPA</strong> обычно акцентирует фруктовую хмелевую ароматику, более мягкую текстуру и мутность; воспринимаемая горечь может быть сдержаннее. Мутность не является самостоятельным доказательством качества.</p>\n<p><strong>Double / Imperial IPA</strong> обозначает более мощное направление, но не буквально «двойной алкоголь». <strong>Session IPA</strong> обычно означает более низкую крепость относительно обычного IPA, без единой всемирной границы. <strong>Dry hopped</strong> сообщает о приёме охмеления, а не автоматически о сладости или отсутствии горечи.</p>\n<p><strong>В рекомендации:</strong> спрашиваем отдельно про аромат и горечь. «Хотите яркий фруктовый аромат с мягким вкусом или сухой, выраженно горький вариант?» Конкретную крепость и IBU проверяем, не вычисляем по названию.</p><p><strong>Источники:</strong> <a href=\"https://www.bjcp.org/style/2021/21/21A/american-ipa/\" target=\"_blank\" rel=\"noopener noreferrer\">BJCP: American IPA</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/ipa-styles-explained-what-neipa-wcipa-and-dipa-actually-mean\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: современные направления IPA</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/how-much-do-you-know-about-hops\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: хмель и способы охмеления</a></p></div></details><details><summary>7. Портер, стаут и обжаренные оттенки</summary><div>\n<p>Porter и Stout — родственные группы с большим разнообразием. Нельзя определять их одним универсальным правилом «портер слабый, стаут крепкий». Оба могут иметь хлебные, карамельные, кофейные и шоколадные впечатления.</p>\n<ul><li><strong>Irish Stout:</strong> часто сухой обжаренный профиль; разлив с азотной смесью может создавать характерную кремовую текстуру и плотную пену. Бутылочное исполнение может ощущаться иначе.</li><li><strong>Sweet / Milk Stout:</strong> сладкое направление; в milk stout обычно используется лактоза. Проверяем молочные компоненты и сведения об аллергенах.</li><li><strong>Oatmeal Stout:</strong> овёс может поддерживать округлую, шелковистую текстуру.</li><li><strong>Imperial Stout:</strong> более крепкое и интенсивное направление, часто с глубокой обжаренностью и сложным ароматом.</li><li><strong>Porter:</strong> несколько традиций и подстилей, которые могут различаться по брожению, крепости и балансу.</li></ul>\n<p>Шоколадный и кофейный аромат часто связан с обжаренным зерном, но в некоторых рецептах действительно добавлены какао или кофе. Поэтому по аромату нельзя ни подтвердить добавку, ни гарантировать её отсутствие.</p>\n<p>Перед предложением уточняем сладость, желаемую крепость и отношение к обжаренной горечи. «Тёмное» — слишком широкое описание.</p><p><strong>Источники:</strong> <a href=\"https://www.bjcp.org/style/2021/15/15B/irish-stout/\" target=\"_blank\" rel=\"noopener noreferrer\">BJCP: Irish Stout</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/the-mystery-of-chocolate-aromas-in-stout-explained\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: обжаренные солода и стаут</a></p></div></details><details><summary>8. Кислые, фруктовые и безалкогольные варианты</summary><div>\n<p>В <strong>sour beer</strong> кислотность является задумкой стиля. Она может формироваться при работе определённых культур и разных технологических подходах. <strong>Lambic</strong> связан с традицией спонтанного брожения, <strong>Gueuze</strong> — с купажированием ламбиков и дображиванием. Фруктовые версии могут быть сухими или сладкими; слово cherry не определяет сахар.</p>\n<p>Кислый вкус у стиля, который должен быть чистым и некислым, требует проверки. Намеренная кислотность не даёт оснований продавать любое скисшее пиво как sour. Brettanomyces — дрожжи, а не молочнокислая бактерия; их ароматический вклад и кислотность нельзя считать одним явлением.</p>\n<h3>Безалкогольное и low alcohol</h3><p>Используют ограничение образования алкоголя, его последующее удаление или другие технологии. Названия «безалкогольное», low alcohol и 0.0 не имеют одной универсальной мировой границы. Проверяем фактическую маркировку продукта для данного рынка и не обещаем абсолютный ноль по одному названию категории.</p>\n<p>Безалкогольный вариант не обязательно не содержит глютен, сахара или аллергенов. Если гостю важны эти параметры, используем только подтверждённую информацию. Сидр — сброженный яблочный напиток, а не разновидность пива.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/what-is-sour-beer-how-its-made-and-sour-beer-styles-to-try\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: кислые стили</a> · <a href=\"https://www.heineken.com/us/en/our-beers/heineken-0-0\" target=\"_blank\" rel=\"noopener noreferrer\">Heineken: пример удаления алкоголя</a></p></div></details><details><summary>9. ABV, плотность, IBU и цвет</summary><div>\n<ul><li><strong>ABV / % об.:</strong> объёмная доля алкоголя в готовом напитке.</li><li><strong>Начальная плотность / экстрактивность:</strong> характеристика сусла до брожения. Градусы Plato и алкогольные проценты — разные показатели. Из одной начальной плотности нельзя точно установить итоговый алкоголь без данных о сбраживании.</li><li><strong>IBU:</strong> аналитический ориентир горечи, а не универсальная шкала того, насколько горьким пиво покажется человеку. Сладость, тело, кислота и другие компоненты меняют восприятие.</li><li><strong>EBC / SRM:</strong> шкалы цвета. Чем выше число, тем темнее образец; эти числа не измеряют крепость.</li><li><strong>Карбонизация:</strong> содержание и восприятие растворённого газа; влияет на текстуру и подачу.</li><li><strong>Тело:</strong> от лёгкого и сухого до полного и округлого; это не то же самое, что цвет.</li></ul>\n<p>Бутылка 12°P не означает 12% алкоголя. Пиво с более высоким IBU может восприниматься мягче на фоне более полного солодового тела. Интенсивный тропический аромат не доказывает ни сок в рецепте, ни высокую сладость.</p>\n<p>Для гостя переводим показатели в ощущения: «умеренная горечь», «сухой финиш», «полная текстура». Числа называем, когда они известны и помогают выбору.</p><p><strong>Источники:</strong> <a href=\"https://www.bjcp.org/download/2021_guidelines_consolidated-pdf\" target=\"_blank\" rel=\"noopener noreferrer\">BJCP: руководство по стилям</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/what-s-in-a-beer-colour-how-shades-tell-a-story/\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: цвет пива</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/how-to-become-a-better-beer-taster\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: дегустация пива</a></p></div></details><details><summary>10. Дегустация, свежесть и дефекты</summary><div>\n<p>Оцениваем внешний вид относительно стиля, затем чистоту аромата, солодовый и хмелевой характер, брожение, вкус, тело, карбонизацию и послевкусие. Описание строим на двух-трёх ясных признаках, а не на рейтинге или модном названии.</p>\n<ul><li><strong>Несвежесть / окисление:</strong> потеря яркости, бумажные и картонные впечатления; время и тепло ускоряют изменения.</li><li><strong>Световое повреждение:</strong> характерный резкий посторонний запах у восприимчивого пива после воздействия света. Упаковка и хранение имеют значение.</li><li><strong>Маслянистый тон:</strong> диацетил может быть частью допустимого профиля отдельных стилей, но выраженный неожиданный тон требует проверки.</li><li><strong>Нежелательная кислота, уксусный запах, необычное вспенивание:</strong> повод остановить продажу и проверить продукт и линию.</li></ul>\n<p>Мутность у Hazy IPA или дрожжевого пшеничного не равна порче; для другого пива изменение прозрачности может быть сигналом. Пена зависит от стиля, газа, температуры и чистоты стекла, поэтому сама по себе не доказывает свежесть.</p>\n<p>При жалобе не спорим, изолируем проблемную подачу, приглашаем ответственного, проверяем партию и систему. Не смешиваем остатки и не маскируем дефект гарниром.</p><p><strong>Источники:</strong> <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2025/how-to-become-a-better-beer-taster\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: дегустация пива</a> · <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2019/06/Draught-Beer-Quality-for-Retailers.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: свежесть и хранение</a> · <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2019/03/13094643/Draught-Beer-Quality-Manual-2019.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: причины посторонних вкусов</a></p></div></details><details><summary>11. Бокал, налив, температура и хранение</summary><div>\n<h3>Чистый бокал</h3><p>Стекло должно быть чистым внутри и снаружи, без жира, помады, запаха моющего средства и сколов. Не доливаем в использованный бокал. Не касаемся внутренней поверхности и края. Признаки недостаточной чистоты — неравномерное смачивание водой и скопления пузырьков на стенках; оцениваем их вместе с процедурой мойки.</p>\n<h3>Налив</h3><p>Подбираем бокал и запас места для пены по стилю. Обычный налив начинают в наклонённый бокал и постепенно выпрямляют, формируя пену; высота пены и техника зависят от продукта. Кран не погружают в напиток. Азотные системы, боковые краны и отдельные стили требуют своей процедуры — не применяем к ним один шаблон.</p>\n<h3>Температура и запас</h3><p>Систему розлива держим в установленном рабочем режиме по инструкции поставщика и оборудования. Не повышаем температуру кега ради более тёплой подачи отдельного стиля. Температура в бокале и температура работы системы — разные задачи. Ледяной бокал и переохлаждение могут скрывать аромат и влиять на пену.</p>\n<p>Защищаем пиво от света и тепла, соблюдаем холодовую цепь, если она предусмотрена. Проверяем срок, дату подключения и партию, используем ротацию запасов. Единого срока после подключения кега для всех марок нет: действуют требования производителя и карта бара.</p><p><strong>Источники:</strong> <a href=\"https://www.cicerone.org/us-en/node/9406\" target=\"_blank\" rel=\"noopener noreferrer\">Cicerone: чистота пивного бокала</a> · <a href=\"https://www.cicerone.org/sites/default/files/certification-syllabi/International_English_CBS_Syllabus_V3.2.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Cicerone: требования к сервису</a> · <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2022/04/04193712/BP22-DBQMR-FINAL.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: качество разливного пива</a> · <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2019/06/Draught-Beer-Quality-for-Retailers.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: свежесть и хранение</a></p></div></details><details><summary>12. Линии розлива и действия при проблеме</summary><div>\n<p>Чистая линия — часть вкуса готовой порции. Рекомендации Brewers Association предусматривают регулярную очистку пивных линий, часто с ориентиром на двухнедельный цикл; конкретный график устанавливают по системе, продукту, требованиям поставщика и местным правилам. Ведём журнал, не заменяем мойку простым проливом водой.</p>\n<ul><li><strong>Слишком много пены:</strong> проверяем температуру, достаточное охлаждение кега, правильность подключения и состояние линии. Не устраняем проблему бесконтрольным изменением давления.</li><li><strong>Слабая карбонизация или пена:</strong> учитываем газ, баланс системы, бокал и сам стиль, а не сразу объявляем пиво испорченным.</li><li><strong>Посторонний запах или вкус:</strong> останавливаем продажу линии, сообщаем ответственному, проверяем пиво, кег и санитарное состояние.</li><li><strong>После обслуживания:</strong> линию возвращают в работу только по утверждённой процедуре с подтверждением удаления моющих средств.</li></ul>\n<p>Давление, газовую смесь и химические концентрации не назначают по общему учебному тексту. Эти параметры зависят от оборудования и продукта. Работу с баллонами и моющими средствами выполняют обученные ответственные сотрудники по инструкции.</p><p><strong>Источники:</strong> <a href=\"https://www.brewersassociation.org/educational-publications/draught-beer-quality-manual/\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: руководство по розливу</a> · <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2022/04/04193712/BP22-DBQMR-FINAL.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: качество разливного пива</a></p></div></details><details><summary>13. Гастрономия и рекомендация гостю</summary><div>\n<p>Начинаем с интенсивности: деликатную еду легко перекрыть мощным IPA или Imperial Stout. Затем ищем созвучие ароматов либо контраст, который нравится гостю. Соус, обжарка, соль, сладость и острота влияют на выбор.</p>\n<ul><li><strong>Лёгкий лагер:</strong> возможный партнёр лёгких закусок, рыбы и не слишком насыщенных жареных блюд.</li><li><strong>Пшеничное:</strong> может поддержать мягкие сыры, салаты и блюда с цитрусовыми или пряными акцентами.</li><li><strong>Янтарный солодовый стиль:</strong> хлебные и тостовые ноты могут сочетаться с запечённым мясом и карамелизированными овощами.</li><li><strong>Pale Ale / IPA:</strong> возможны сочетания с насыщенными блюдами и сырами; сильная горечь и алкоголь могут усиливать неприятное жжение от чили.</li><li><strong>Портер / стаут:</strong> обжаренные оттенки могут работать с грилем или шоколадным десертом, но сухой стаут и сладкий Imperial Stout требуют разных решений.</li><li><strong>Кислый или фруктовый стиль:</strong> сопоставляем реальную кислотность, сладость и насыщенность блюда.</li></ul>\n<p>Это учебные примеры, не обязательные пары. Уточняем: мягкое или горькое → лёгкое или насыщенное → желаемая крепость → любимые ароматы → блюдо и бюджет. Предлагаем реальные позиции из меню, проверяем наличие и называем цену.</p>\n<p><strong>Шаблон карточки:</strong> стиль; страна и пивоварня; крепость; подтверждённые показатели; сырьё и аллергены; стилистика; дегустационные характеристики; гастрономия; производство и подача.</p><p><strong>Источники:</strong> <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2017/04/Beer_and_Food_English.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: пиво и еда</a> · <a href=\"https://cdn.brewersassociation.org/wp-content/uploads/2019/06/Craft-Beer-and-Food-Pairing-Guide.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Brewers Association: примеры сочетаний</a> · <a href=\"https://www.wsetglobal.com/knowledge-centre/blog/2026/how-to-pair-drinks-with-spice\" target=\"_blank\" rel=\"noopener noreferrer\">WSET: напитки и острые блюда</a></p></div></details>"}}$guide$::jsonb);
commit;
select jsonb_agg(jsonb_build_object('id',id,'published',published,'sections',payload->'sectionCount')) from public.academy_content where id in ('bar-wine-guide','bar-beer-guide');
